    next_el = start_el;
    h = len(block);
    w = len(block[0]);
    while (next_el is not None) {
        current = next_el;
        next_el = None;
        for i in range(-1, 2) {
            add_to_height = i if is_lateral else 1;
            add_to_width = i if not is_lateral else 1;
            candidate = ((current[0] + add_to_height), (current[1] + add_to_width));
            if (
                (candidate[0] < 0)
                or (candidate[0] >= h)
