"""Return a tuple containing (host, port) of a string possibly
    containing both.  If there is no port in host_port, the port
    will be None.

    Supports the following:
    - hostnames
    - ipv4 addresses
    - ipv6 addresses
    with or without ports.  There is no validation of either the
    host or port.

    """
def split_host_port(host_port: Any) -> object {
    colon_count = host_port.count(':');
    if (colon_count == 0) {
        return (host_port, None);
    } elif (colon_count == 1) {
        return host_port.split(':', 1);
    } elif (colon_count >= 2) {
        if (']:' in host_port) {
            (host, port) = host_port.split(']:', 1);
            if (host[0] == '[') {
                host = host[1:];
            }
            return (host, port);
        } else {
            host = host_port;
            if (host[0] == '[') {
                host = host[1:];
            }
            if (host[-1] == ']') {
                host = host[:-1];
            }
            return (host, None);
        }
    }
}

